render:
const { root, params, time, width, height } = ctx;
const canvas = root.querySelector('#board-canvas');
if (!canvas) return;

if (canvas.width !== width || canvas.height !== height) {
  canvas.width = width;
  canvas.height = height;
}

const c = canvas.getContext('2d');

const boardStyle = params.board_style || 1;
const stringColor = params.string_color || '#FF2233';
const stringTension = params.string_tension !== undefined ? params.string_tension : 0.4;
const stringDensity = params.string_density || 2;
const pulseSpeed = params.pulse_speed || 1.0;
const showPulse = params.show_pulse !== false;
const centralLabel = params.central_label !== undefined ? params.central_label : 'SOSPECHOSO X';
const questionColor = params.question_color || '#FFD700';
const flashlightMode = params.flashlight_mode !== false;
const dustParticles = params.dust_particles !== false;
const cardCount = params.card_count || 6;
const cardBg = params.card_bg || '#F4E8C1';
const pinColor = params.pin_color || '#E60000';
const glowIntensity = params.glow_intensity !== undefined ? params.glow_intensity : 0.8;
const fontFamily = params.font_family || 'Courier New, monospace';

// 1. DIBUJAR FONDO SEGÚN ESTILO
c.save();
if (boardStyle === 1) {
  c.fillStyle = '#3D2817';
  c.fillRect(0, 0, width, height);
  c.fillStyle = 'rgba(0, 0, 0, 0.15)';
  for (let x = 0; x < width; x += 8) {
    for (let y = 0; y < height; y += 8) {
      if ((x + y) % 16 === 0) c.fillRect(x, y, 4, 4);
    }
  }
} else if (boardStyle === 2) {
  c.fillStyle = '#1A110C';
  c.fillRect(0, 0, width, height);
  c.fillStyle = '#261912';
  const plankW = width / 8;
  for (let i = 0; i < 8; i += 2) {
    c.fillRect(i * plankW, 0, plankW, height);
  }
} else {
  c.fillStyle = '#181C1E';
  c.fillRect(0, 0, width, height);
}
c.restore();

const cx = width / 2;
const cy = height / 2;
const centerW = 130;
const centerH = 175;
const centerPinY = cy - centerH / 2 + 12;

// 2. CALCULAR POSICIONES DE TARJETAS ALREDEDOR
const outerCards = [];
const radiusX = Math.min(width, height) * 0.36;
const radiusY = Math.min(width, height) * 0.30;

for (let i = 0; i < cardCount; i++) {
  const angle = (i / cardCount) * Math.PI * 2 - Math.PI / 2;
  const floatOffset = Math.sin(time * 1.5 + i) * 3;
  const x = cx + Math.cos(angle) * radiusX;
  const y = cy + Math.sin(angle) * radiusY + floatOffset;
  const tilt = Math.sin(i * 12.3) * 0.2;
  const pinX = x;
  const pinY = y - 38;
  outerCards.push({ x, y, pinX, pinY, tilt, id: i });
}

// Función auxiliar para dibujar curvas bezier cuadráticas (hilos)
function drawThread(p1x, p1y, p2x, p2y, offsetIdx) {
  const mx = (p1x + p2x) / 2;
  const my = (p1y + p2y) / 2 + stringTension * 65;

  c.save();
  c.strokeStyle = 'rgba(0,0,0,0.4)';
  c.lineWidth = 3;
  c.beginPath();
  c.moveTo(p1x, p1y + 3);
  c.quadraticCurveTo(mx, my + 3, p2x, p2y + 3);
  c.stroke();

  c.strokeStyle = stringColor;
  c.lineWidth = 2;
  c.beginPath();
  c.moveTo(p1x, p1y);
  c.quadraticCurveTo(mx, my, p2x, p2y);
  c.stroke();
  c.restore();

  if (showPulse) {
    const progress = ((time * pulseSpeed * 0.5) + offsetIdx * 0.2) % 1.0;
    const inv = 1 - progress;
    const px = inv * inv * p1x + 2 * inv * progress * mx + progress * progress * p2x;
    const py = inv * inv * p1y + 2 * inv * progress * my + progress * progress * p2y;

    c.save();
    c.fillStyle = '#FFFFFF';
    c.shadowColor = stringColor;
    c.shadowBlur = 10 * glowIntensity;
    c.beginPath();
    c.arc(px, py, 3.5, 0, Math.PI * 2);
    c.fill();
    c.restore();
  }
}

// 3. DIBUJAR HILOS ROJOS ENTRE PISTAS
for (let i = 0; i < outerCards.length; i++) {
  const card = outerCards[i];
  drawThread(card.pinX, card.pinY, cx, centerPinY, i);

  if (stringDensity === 2) {
    const nextCard = outerCards[(i + 1) % outerCards.length];
    drawThread(card.pinX, card.pinY, nextCard.pinX, nextCard.pinY, i + 10);
  }
}

// 4. DIBUJAR TARJETAS PERIFÉRICAS (POLAROIDS / NOTAS)
for (let i = 0; i < outerCards.length; i++) {
  const card = outerCards[i];
  c.save();
  c.translate(card.x, card.y);
  c.rotate(card.tilt);

  c.fillStyle = 'rgba(0, 0, 0, 0.35)';
  c.fillRect(-42, -42, 90, 100);

  c.fillStyle = cardBg;
  c.fillRect(-45, -45, 90, 100);

  c.fillStyle = '#1A1A1A';
  c.fillRect(-37, -37, 74, 60);

  c.fillStyle = 'rgba(255, 255, 255, 0.08)';
  c.fillRect(-37, -37, 74, 30);

  c.fillStyle = '#3A3A3A';
  c.fillRect(-30, 28, 40, 4);
  c.fillRect(-30, 36, 60, 4);
  c.restore();

  // Chinche
  c.save();
  c.fillStyle = pinColor;
  c.shadowColor = '#000000';
  c.shadowBlur = 4;
  c.beginPath();
  c.arc(card.pinX, card.pinY, 6, 0, Math.PI * 2);
  c.fill();
  c.restore();
}

// 5. DIBUJAR TARJETA CENTRAL DE LA SILUETA (SOSPECHOSO Principal)
c.save();
c.translate(cx, cy);

c.fillStyle = 'rgba(0, 0, 0, 0.5)';
c.fillRect(-centerW / 2 + 5, -centerH / 2 + 5, centerW, centerH);

c.fillStyle = '#111318';
c.strokeStyle = questionColor;
c.lineWidth = 2;
c.beginPath();
c.roundRect(-centerW / 2, -centerH / 2, centerW, centerH, 6);
c.fill();
c.stroke();

// Silueta humana en sombras
c.fillStyle = '#07080A';
c.beginPath();
c.arc(0, -20, 28, 0, Math.PI * 2);
c.fill();

c.beginPath();
c.ellipse(0, 45, 48, 38, 0, Math.PI, 0, true);
c.fill();

// Signo de interrogación vibrando / latiendo
const pulseScale = 1 + Math.sin(time * 4) * 0.08;
const pulseGlow = (12 + Math.sin(time * 4) * 8) * glowIntensity;

c.save();
c.scale(pulseScale, pulseScale);
c.fillStyle = questionColor;
c.shadowColor = questionColor;
c.shadowBlur = pulseGlow;
c.font = 'bold 54px ' + fontFamily;
c.textAlign = 'center';
c.textBaseline = 'middle';
c.fillText('?', 0, -8);
c.restore();

if (centralLabel.trim().length > 0) {
  c.fillStyle = '#FFFFFF';
  c.font = 'bold 12px ' + fontFamily;
  c.textAlign = 'center';
  c.textBaseline = 'bottom';
  c.fillText(centralLabel, 0, centerH / 2 - 12);
}
c.restore();

// Chinche central
c.save();
c.fillStyle = pinColor;
c.shadowColor = '#000000';
c.shadowBlur = 5;
c.beginPath();
c.arc(cx, centerPinY, 8, 0, Math.PI * 2);
c.fill();
c.restore();

// 6. POLVO AMBIENTAL SUSPENDIDO
if (dustParticles) {
  c.save();
  c.fillStyle = '#FFFFFF';
  for (let p = 0; p < 25; p++) {
    const px = (Math.sin(p * 99 + time * 0.2) * 0.5 + 0.5) * width;
    const py = (Math.cos(p * 33 + time * 0.15) * 0.5 + 0.5) * height;
    c.globalAlpha = 0.15 + Math.sin(time + p) * 0.1;
    c.fillRect(px, py, 2, 2);
  }
  c.restore();
}

// 7. EFECTO LINTERNA / LUZ DE DETECTIVE
if (flashlightMode) {
  c.save();
  const lx = cx + Math.sin(time * 0.8) * (width * 0.22);
  const ly = cy + Math.cos(time * 0.6) * (height * 0.18);

  const lightGrad = c.createRadialGradient(lx, ly, 80, lx, ly, Math.max(width, height) * 0.65);
  lightGrad.addColorStop(0, 'rgba(0,0,0,0)');
  lightGrad.addColorStop(0.5, 'rgba(0,0,0,0.3)');
  lightGrad.addColorStop(1, 'rgba(0,0,0,0.82)');

  c.fillStyle = lightGrad;
  c.fillRect(0, 0, width, height);
  c.restore();
}
